import{_ as t}from"./chunks/layer-settings.Dcq49T8r.js";import{_ as r,o as a,c as o,a2 as s}from"./chunks/framework.Boholvbs.js";const n="/docs/assets/post-type-layers.CTPbwUWi.png",i="/docs/assets/layer-sidebar.B5E1sVhu.png",d="/docs/assets/layer-interactions.dizQJPUZ.png",l="/docs/assets/layer-legend.D-8wFCMi.png",_=JSON.parse('{"title":"Creating a layer","description":"","frontmatter":{},"headers":[],"relativePath":"layer-post.md","filePath":"layer-post.md"}'),p={name:"layer-post.md"};function c(h,e,y,g,u,m){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="creating-a-layer" tabindex="-1">Creating a layer <a class="header-anchor" href="#creating-a-layer" aria-label="Permalink to &quot;Creating a layer&quot;">​</a></h1><p>One of the custom post types that JEO plugin provides is <strong>Layer</strong>. Layers are where you add legends, colors, and data sources to your maps. A map may contain one or more layers.</p><p><img src="'+n+'" alt="Post Type Layers"></p><p>Entering the Layer post editor, you&#39;ll see a preview of the current layer (or a default layer if the current layer hasn&#39;t been edited yet) and three sidebar panels: <strong>Settings</strong>, <strong>Attributions</strong> and <strong>Legend</strong>.</p><p><img src="'+i+'" alt="Layer Sidebar"></p><h2 id="layer-settings" tabindex="-1">Layer settings <a class="header-anchor" href="#layer-settings" aria-label="Permalink to &quot;Layer settings&quot;">​</a></h2><p>On the <strong>Layer settings</strong> panel, you can change the layer type.</p><p>JEO supports seven layer types out-of-the-box:</p><table tabindex="0"><thead><tr><th>Type</th><th>Required fields</th><th>Optional fields</th><th>Best for</th></tr></thead><tbody><tr><td><a href="https://docs.mapbox.com/studio-manual/overview/map-styling/" target="_blank" rel="noreferrer">Mapbox styles</a></td><td>Style ID (<code>username/style-id</code>)</td><td>Access token</td><td>Complete styled maps created in Mapbox Studio</td></tr><tr><td><a href="https://maplibre.org/maplibre-style-spec/" target="_blank" rel="noreferrer">Style JSON</a></td><td>Style URL or inline style JSON</td><td>—</td><td>Public MapLibre GL styles; works without an API key</td></tr><tr><td><a href="https://docs.mapbox.com/help/glossary/tileset/" target="_blank" rel="noreferrer">Mapbox tilesets</a> (raster)</td><td>Tileset ID (<code>username.tilesetid</code>)</td><td>Access token</td><td>Raster data hosted on Mapbox</td></tr><tr><td><a href="https://docs.mapbox.com/vector-tiles/reference/" target="_blank" rel="noreferrer">Mapbox vector tilesets</a></td><td>Tileset ID, source layer</td><td>Access token</td><td>Vector data hosted on Mapbox</td></tr><tr><td><a href="https://docs.mapbox.com/vector-tiles/reference/" target="_blank" rel="noreferrer">Mapbox vector tiles</a> (MVTs)</td><td>Tileset URL, source layer, geometry type</td><td>Access token</td><td>Vector data with interactive features</td></tr><tr><td><a href="https://geojson.org/" target="_blank" rel="noreferrer">GeoJSON</a></td><td>GeoJSON URL or inline GeoJSON</td><td>Layer style</td><td>Client-side polygon data, including AI-generated boundary layers</td></tr><tr><td><a href="https://en.wikipedia.org/wiki/Tiled_web_map" target="_blank" rel="noreferrer">TileLayers</a></td><td>Tile URL template (<code>https://.../{z}/{x}/{y}.png</code>)</td><td>—</td><td>Third-party tile servers (XYZ URLs)</td></tr></tbody></table><p>If the <strong>Access token</strong> field is left empty, the layer will use the Mapbox API key configured in <strong>Jeo → Settings</strong>. You only need to fill this field when the layer requires a different token than the global one.</p><p><img src="'+t+'" alt="Layer settings"></p><p>There&#39;s also an <strong>Edit interactions</strong> button. Here, you can add popups to your layer when specific actions (clicking or hovering the mouse) are made (e.g.: clicking on a building and displaying its height).</p><p><img src="'+d+'" alt="Layer interactions"></p><h2 id="layer-legend" tabindex="-1">Layer legend <a class="header-anchor" href="#layer-legend" aria-label="Permalink to &quot;Layer legend&quot;">​</a></h2><p>On the <strong>Layer legend</strong> panel, you can add legends to your layer (barscale, simple-color, icons, or circles) and customize their colors.</p><p><img src="'+l+'" alt="Layer legend"></p><h2 id="attributions" tabindex="-1">Attributions <a class="header-anchor" href="#attributions" aria-label="Permalink to &quot;Attributions&quot;">​</a></h2><p>Here is where you can give layer credits, setting a link to download it or access more information about it. These attributions will be shown on the bottom of the map and inside the popup that shows up when the <code>INFO</code> button is clicked in a map.</p>',18)])])}const k=r(p,[["render",c]]);export{_ as __pageData,k as default};
